import pandas as pd

def clean(df):
    df = df.copy()
    df = df.drop_duplicates()
    df['Category'] = df['Category'].replace('Furnture', 'Furniture')
    df['Region'] = df['Region'].str.strip()
    df['Price'] = pd.to_numeric(df['Price'], errors='coerce')
    return df

def answer(df):
    return df.groupby('Category')['Price'].mean().round(2).to_dict()
